contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: addr to set and a flag whether to attempt transfer
    function run(address initialOwner, address newOwner, bool doTransfer) public payable {
        require(initialOwner != address(0)); // ensure deployer can be set
        // set up: we must make this contract be the owner before testing transferOwnership
        // The supplied contract C was freshly deployed; its owner is initially zero address.
        // We simulate ownership setup by calling transferOwnership from the contract only if current owner is address(this).
        // But since onlyOwner requires msg.sender == owner, the only way to set owner to initialOwner is if owner is address(this).
        // To ensure owner == initialOwner for the property, we first check current owner; if it's not address(this), we cannot call onlyOwner functions.
        // Instead, we will reason about two cases: if msg.sender (this contract) is the owner then transferOwnership should succeed and update owner;
        // otherwise transferOwnership should revert and owner should stay as before.

        // Read owner before any action
        address ownerBefore = c.owner();

        bool didRevert = false;
        if (doTransfer) {
            // attempt transferOwnership from this contract
            try c.transferOwnership(newOwner) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        address ownerAfter = c.owner();

        // General rule:
        // - If we did call transferOwnership (doTransfer==true): then it must succeed (didRevert==false) exactly when ownerBefore == address(this).
        //   If it succeeded then ownerAfter == newOwner. If it reverted then ownerAfter == ownerBefore.
        // - If we did not call transfer, owner is unchanged.
        assert(
            // when not attempting transfer, nothing changes
            (doTransfer == false && ownerAfter == ownerBefore)
            ||
            // when attempting transfer: success iff caller was owner, and success implies owner updated
            (doTransfer == true && (
                (didRevert == false && ownerBefore == address(this) && ownerAfter == newOwner)
                ||
                (didRevert == true && ownerAfter == ownerBefore)
            ))
        );
    }

    receive() external payable {}
}

