    // single public test function taking inputs: caller address and candidate new owner
    function run(address caller, address newOwner) public payable {
        require(address(this).balance >= 0); // no-op to allow payable, but ensures function compiles with payable

        // Read initial owner
        address beforeOwner = c.owner();

        // We will attempt to call transferOwnership from this contract (msg.sender == this contract)
        // but we want to model calls that may come from other callers. The checker runs run() once
        // with this contract as the caller for c; to simulate different callers, we use only the
        // existing public surface. Since only msg.sender is used by C, and it will be this contract,
        // we can only observe behavior for this contract as caller. Therefore the property will
        // assert the relation between revert and owner change for the actual caller (this contract).

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address afterOwner = c.owner();

        // General rule: if the call reverted then owner did not change; if it did not revert then owner equals newOwner.
        assert(reverted ? (afterOwner == beforeOwner) : (afterOwner == newOwner));
    }

    receive() external payable { }
